package com.a24solver.wakusei.sound

/**
 * The pitches the keypad can play, as equal-temperament frequencies (A4 = 440 Hz).
 *
 * Nothing here is a recording: every note is generated by [ToneSynthesizer] at playback time, so
 * the app ships no audio files and cannot carry anyone else's samples.
 */
enum class Pitch(val frequencyHz: Double, val noteName: String) {
    C4(261.63, "C"),
    D4(293.66, "D"),
    E4(329.63, "E"),
    F_SHARP4(369.99, "F#"),
    G4(392.00, "G"),
    A4(440.00, "A"),
    B_FLAT4(466.16, "Bb"),
    C5(523.25, "C5"),
    E_FLAT4(311.13, "Eb"),
    G_SHARP4(415.30, "G#"),
    B4(493.88, "B")
}
